    private var cache = mutableMapOf<String, ImageVector>()

    private fun build(name: String, pathData: String, fillAlpha: Float = 1f): ImageVector {
        val nodes = addPathNodes(pathData)
        return ImageVector.Builder(name = name, defaultWidth = 24.dp, defaultHeight = 24.dp,
            viewportWidth = 24f, viewportHeight = 24f).apply {
            addPath(pathData = nodes, fill = SolidColor(Color.Black), fillAlpha = fillAlpha)
        }.build()
    }

